def _n1(clase, html, titulo, lema, gp, **kw):
    d = dict(nivel='1', clase=clase, html=html, titulo=titulo, lema=lema, edad='de 8 a 12 años', dur='50', gram_pages=gp,
             gram_ref=f'cap. {clase}, págs. {gp[0]}–{gp[-1]}', antes_min='10', final_t='Al final, para jugar')
    d.update(kw); L['n1c' + clase] = d

