_n2('1', 'aula-n2-clase-1-es.html', 'El camino de una obra', 'Repaso del Nivel 1 y las señales de la partitura', [7, 8, 9, 10],
  gram_ref='«El viaje de los sonidos», págs. 5–6, y cap. 1, págs. 7–10', antes_min='15',
  gram_desc='«El viaje de los sonidos» (págs. 5 y 6) y «El camino de una obra» (págs. 7 a 10): la anacrusa, las barras de repetición, las dobles barras y la Coda.',
  meta=f'Mientras escuchan {ALLA} de Mozart con la partitura proyectada, los alumnos <b>señalan la anacrusa, las barras de repetición, las dobles barras y la Coda</b>, y dicen cuántas veces suena cada parte. Además: leer la «Oda a la alegría» con sílabas y nombres, y escribir un ritmo de cuatro pulsos que se oye.',
  necesita='Un computador con parlante e internet, la pizarra y, si es posible, un proyector. Viene bien haber hecho el Nivel 1. No hace falta saber música: la partitura se ilumina mientras suena.',
  antes=[f'Abra {ALLA} en el Score y escúchela entera: las cuatro notas rápidas antes de la primera barra son la anacrusa; en el compás 8, la barra de repetición.', f'Abra también la {ODA}, y el {KB} con <b>pulse</b> a unos 60 BPM para el dictado.', 'Recuerde ⛶ FULL, − / + y la perilla de ♩ PULSE.'],
  etapas=[('3', 'La meta', '<i>«Una partitura no se lee siempre de corrido: tiene señales que dicen por dónde ir.»</i> En la pizarra: <b>Puedo seguir el camino de una obra en la partitura.</b>', 'pizarra'),
   ('12', 'Lo que ya saben: leer y escribir', f'<b>Leer</b>: la «Oda a la alegría», la clave, el compás, el ritmo con sílabas y los nombres; ▶ para comprobar. <b>El dictado</b>: usted toca en {k("Z")} un ritmo de cuatro pulsos y lo escribe; después tocan otro y lo escriben los alumnos.', 'cancion'),
   ('13', 'Lo nuevo: los signos del camino', '<b>Viena, 1783</b>: de dónde viene «Alla Turca». <b>La anacrusa</b>: cuatro notas rápidas que duran un pulso; la obra empieza en el dos. <b>Repetir y terminar</b>: la barra de repetición («vuelve y tócalo otra vez»), las dobles barras, la Coda y el rit. del final.', 'repeticion'),
   ('17', 'Aplicación: seguir el camino', 'Usted muestra los primeros 8 compases con el dedo y dice «¡otra vez!» en la repetición. Después, tres grupos: uno levanta la mano en cada barra de repetición, otro en cada doble barra, otro en la Coda; la obra suena entera y la clase reconstruye el camino en la pizarra.', 'pentagrama'),
   ('5', 'El repaso de la meta', '<i>«¿Qué es una anacrusa? ¿Qué dicen los dos puntos de una barra? ¿Por qué el final se llama Coda?»</i> Y: <i>«¿Qué la hace sonar a marcha?»</i>', 'pulgar')],
  cuesta='No ven la anacrusa: cuenten los compases desde la primera barra; la nota de antes queda «fuera de la casa». Se pierden al repetir: la obra más lenta con la perilla y diga «otra vez» en voz alta. Confunden doble barra y barra final: la final tiene una barra gruesa. El dictado cuesta: primero con sílabas y palmas, después escrito.',
  funciono='Al escuchar «Alla Turca», <b>la mayoría de los grupos</b> hace su señal en el lugar correcto y la clase reconstruye el camino de la obra; la mayoría lee la «Oda» con sílabas y escribe bien al menos un dictado.',
  final='La ficha del alumno, al final de la guía, y el cuaderno: «El viaje de los sonidos» y «El camino de una obra».',
  eval_que='Grupos que hicieron su señal en el lugar correcto', eval_si_no='empiece la Clase 2 siguiendo otra vez los primeros 8 compases de «Alla Turca» (5 min).',
  palabras=[('Anacrusa', 'Las notas que llegan antes del primer compás completo, como un saltito antes de empezar.'), ('Barras de repetición', 'Dos puntitos junto a la barra: lo que está entre ellas se toca dos veces.'),
   ('Doble barra', 'Dos barras finas: termina una parte. La barra final tiene una gruesa.'), ('Coda', 'En italiano, «cola»: el final especial de la obra.'),
   ('Rit.', 'Ritardando: el pulso se va haciendo más lento.'), ('Allegretto', 'Una palabra de tempo: algo rápido y alegre.'),
   ('Dictado', 'Escribir con figuras lo que se oye.'), ('Partitura', 'La música escrita, con su camino de señales.')])

_n2('2', 'aula-n2-clase-2-es.html', 'Un pedazo y medio', 'Semicorcheas y puntillo', [11, 12],
  gram_desc='«Un pedazo y medio»: la tableta en dieciséis, el «ti-ki-ti-ki», el puntillo y el galope.',
  meta='Cada pareja <b>lee con sílabas y toca en una tecla, al pulso del metrónomo, un compás</b> con una negra con puntillo y su corchea, cuatro semicorcheas y una negra; la clase confirma con el pulgar. Además: explicar con la tableta que el puntillo suma la mitad, y encontrar las negras con puntillo en la voz del «Ave Maria».',
  necesita='Un computador con parlante e internet, la pizarra, <b>espacio para moverse</b> (y un proyector, si hay). Viene bien haber hecho la Clase 1.',
  antes=[f'En el {KB} con <b>pulse</b> a 60 BPM: cuatro notas en {k("Z")} dentro de un clic, «ti-ki-ti-ki»; y el galope, «ta-i ti», que ocupa dos clics.', f'Abra {AVE} en el Score: la voz tiene negras con puntillo seguidas de una corchea. Con ♩ PULSE se pone más lenta.'],
  etapas=[('3', 'La meta', '<i>«Hoy la tableta se parte en dieciséis, y conocemos un puntito que alarga las notas.»</i> En la pizarra: <b>Puedo leer y tocar semicorcheas y notas con puntillo.</b>', 'pizarra'),
   ('5', 'Lo que ya saben: la tableta en ocho', 'Negras («ta») y corcheas («ti-ti») con palmas. <i>«¿Cuántas corcheas caben en una redonda? ¿Y si partimos cada corchea otra vez?»</i>', 'tableta'),
   ('15', 'Lo nuevo: ti-ki-ti-ki y el galope', '<b>Ti-ki-ti-ki</b>: cuatro sílabas en un solo paso («Sol, ma-ri-po-sa»). <b>El puntillo</b>: «2 y la mitad de 2: 3»; la negra con puntillo es un pedazo y medio. <b>El galope</b>: paso largo, paso corto, «ta-i ti»: negra con puntillo y corchea.', 'puntillo'),
   ('22', 'Aplicación: leer, tocar y escuchar', f'<b>El compás de la meta</b>: <i>ta-i ti, ti-ki-ti-ki, ta</i> (1½ + ½ + 1 + 1 = 4); la clase lo dice, una pareja lo toca en {k("Z")} y la clase levanta el pulgar. Después, en el «Ave Maria», buscar las negras con puntillo de la voz.', 'figuras'),
   ('5', 'El repaso de la meta', '<i>«¿Cuántas semicorcheas caben en un pulso? ¿Qué hace el puntillo? ¿Cuánto vale una negra con puntillo?»</i>', 'pulgar')],
  cuesta='Las semicorcheas se aceleran: el metrónomo más lento y «ma-ri-po-sa» en cada pulso. Confunden el puntillo con una nota más: no suena aparte, solo alarga; dejen la tecla apretada. El galope sale parejo: exagere el paso largo. No encuentran los puntillos: la obra más lenta y señálelos usted las primeras veces.',
  funciono='Al menos <b>3 de cada 4 parejas</b> leen y tocan el compás de la meta al pulso; la mayoría explica cuánto suma un puntillo y encuentra negras con puntillo en el «Ave Maria».',
  final='La ficha del alumno, al final de la guía. Reto: ¿cuántas semicorcheas caben en una blanca con puntillo? Doce.',
  eval_que='Parejas que tocaron el compás de la meta', eval_si_no='empiece la Clase 3 diciendo juntos el compás de la meta con sílabas (5 min).',
  palabras=[('Semicorchea', 'Media corchea: cuatro caben en un pulso de negra. Se dice «ti-ki-ti-ki».'), ('Puntillo', 'Un punto al lado de la figura: le suma la mitad de lo que vale.'),
   ('Negra con puntillo', 'Un pulso y medio: un pedazo y medio de tableta.'), ('Blanca con puntillo', 'Tres pulsos: 2 y la mitad de 2.'),
   ('El galope', 'Negra con puntillo y corchea: paso largo, paso corto, «ta-i ti».'), ('La tableta en dieciséis', 'La redonda partida en dieciséis semicorcheas.'),
   ('La voz', 'En la partitura del «Ave Maria», el pentagrama de arriba: lo que se canta.'), ('Pulso', 'El latido de la música; las sílabas caben dentro de él.')])

_n2('3', 'aula-n2-clase-3-es.html', 'Las notas rápidas y los adornos', 'Fusas, tresillos y adornos', [13, 14, 15, 16],
  gram_ref='cap. 3, págs. 13–16',
  edad='de 9 a 14 años · en grupos de 4',
  gram_desc='«Las notas rápidas» y «Los adornos» (págs. 13 a 16).',
  meta='Cada grupo <b>escribe un compás de 2/4 con fusas o con un tresillo y un adorno</b>, lo toca o lo palmea, y la clase dice qué figuras y qué adorno usaron. Además: decir cuántas fusas caben en una negra (8) y en una corchea (4), y nombrar las tres afinaciones en que suena la Sinfonía nº 9 de Bach.',
  necesita=f'Un computador con parlante y proyector, el {KB} y el Score (mejor un computador por grupo), {B9} y {ALLA}. Viene bien haber hecho la Clase 2.',
  antes=[f'Escuche el comienzo de {B9} y busque en el compás 12 el signo del mordente.', 'En el Score, escriba un compás con el <b>NUM PAD</b>: 5 negra, 4 corchea, 3 semicorchea, 2 fusa, 1 semifusa, y reprodúzcalo.', 'Pruebe el tresillo (³ <b>TUPLET</b>, en el menú de la nota) y un adorno (trino y mordente, en <b>ART</b>).'],
  etapas=[('3', 'La meta', '<i>«Hay músicas que corren tanto que la semicorchea no alcanza, y músicos que decoran cada nota.»</i> En la pizarra: <b>Puedo escribir notas rápidas, un tresillo y un adorno.</b>', 'pizarra'),
   ('5', 'Lo que ya saben: la tableta y la semicorchea', 'Una negra en la pizarra: ¿cuántas corcheas caben? ¿y semicorcheas? Palmas con «ti-ti» y «ti-ki-ti-ki».', 'tableta'),
   ('17', 'Lo nuevo: fusas, tresillo y adornos', '<b>La fusa y la semifusa</b>: tres y cuatro barras; ocho fusas en una negra. <b>El tresillo</b>: «ti-ti» y «tri-pe-ta» en el mismo pulso. <b>Los adornos</b>: una nota larga, con trino y con mordente; el compás 12 de Bach y las apoyaturas de «Alla Turca». <b>Bach en tres afinaciones</b>: ¿suenan igual?', 'adornos'),
   ('20', 'Aplicación: un compás con notas rápidas y un adorno', '<b>En papel</b>: usted escribe un ejemplo de 2/4 con un tresillo, una negra y un trino; cada grupo escribe el suyo. <b>En el Score</b>: con NUM PAD, ³ TUPLET y ART, lo reproducen y corrigen. <b>Adivinar</b>: cada grupo lo toca o palmea y la clase dice qué figuras y qué adorno usaron.', 'cancion'),
   ('5', 'El repaso de la meta', '<i>«¿Cuántas fusas caben en una negra? ¿Qué es un tresillo? ¿En qué tres afinaciones escuchamos a Bach?»</i>', 'pulgar')],
  cuesta='Se pierden con las barras: cuéntenlas; cada barra parte la nota a la mitad. El tresillo sale como dos corcheas y una más: «tri-pe-ta» con la palmada solo en «tri». En el Score no encuentran el adorno: primero seleccionan la nota y después abren ART.',
  funciono='Al menos <b>3 de cada 4 grupos</b> escriben un compás de 2/4 que suma bien, con fusas o un tresillo y un adorno; la mayoría dice cuántas fusas caben en una negra y nombra las tres afinaciones de la Sinfonía nº 9.',
  final='La Clase 3b, «Don Quijote sale de viaje»: el repaso de los capítulos 1 a 3 con la música de Telemann.',
  eval_que='Grupos con su compás completo', eval_si_no='empiece la Clase 4 palmeando juntos un tresillo y ocho fusas (5 min).',
  palabras=[('Fusa', 'Media semicorchea: ¡ocho en un pulso! Tres barras.'), ('Semifusa', 'Media fusa: cuatro barras; sesenta y cuatro caben en una redonda.'),
   ('Tresillo', 'Tres notas en el lugar de dos: «tri-pe-ta».'), ('Adornos', 'Notas pequeñas que decoran la melodía: el trino, el mordente, la apoyatura.'),
   ('Trino', 'La nota tiembla rápido con su vecina de arriba.'), ('Mordente', 'Una nota que baja o sube a su vecina y vuelve, muy rápido.'),
   ('Apoyatura', 'Una nota pequeña que se apoya antes de la principal.'), ('Afinación', 'Cómo se reparten las distancias entre las notas: tonal, bien temperada o temperada igual.')])
