_n2('7', 'aula-n2-clase-7-es.html', 'Las dos claves', 'La clave de fa y el sistema', [29, 30, 31, 32],
  gram_desc='«Las dos claves» (págs. 29 y 30) y «Escuchar lo de abajo» (págs. 31 y 32).',
  meta='Cada pareja <b>lee en voz alta las nueve notas del bordón del Seikilos, escritas en clave de fa</b>, y una pareja las toca en el Keyboard junto con la melodía; la clase confirma con el pulgar. Además: dibujar la clave de fa y decir qué nota vive en la cuarta línea, y explicar qué pentagrama de un sistema lleva las notas graves.',
  necesita=f'Un computador con parlante e internet, el {KB}, {SEI2} en el Score (el de la Clase 4 del Nivel 1), la pizarra (y un proyector, si hay). Viene bien haber hecho la Clase 6.',
  antes=[f'Escuche {SEI2} entero: arriba la melodía del aulos, en clave de sol; abajo el bordón de la kithara, en clave de fa, una nota larga por compás.', 'Lea el bordón: Sol, Sol, Mi, Re, Sol, Fa, Sol, Re, Sol.', f'En la fila del medio del {KB}: {k("G")} Sol · {k("F")} Fa · {k("D")} Mi · {k("S")} Re. Toque el bordón con el Seikilos sonando.'],
  etapas=[('3', 'La meta', '<i>«Hoy vamos a leer la parte que tocaba la lira, en una clave nueva.»</i> En la pizarra: <b>Puedo leer las notas en clave de fa.</b>', 'pizarra'),
   ('5', 'Lo que ya saben: la clave de sol', 'Una clave de sol: ¿qué nota vive en la segunda línea? Sol. Dos o tres notas más, contando desde Sol, y la historia de la piedra en dos frases.', 'clave'),
   ('17', 'Lo nuevo: la clave de fa y el sistema', '<b>Dibujar la clave</b>: el punto grueso en la cuarta línea, la vuelta y los dos puntitos; la cuarta línea es Fa. <b>Leer desde Fa</b>: líneas Sol, Si, Re, Fa, La; espacios La, Do, Mi, Sol. <b>El sistema</b>: el pentagrama de arriba para lo agudo, el de abajo para lo grave.', 'clavefa'),
   ('20', 'Aplicación: tocar la kithara', f'<b>Leer el bordón</b>: las nueve notas en voz alta, y cada una en el teclado: {k("G G D S G F G S G")}. <b>Tocar con el Seikilos</b>: usted primero, una tecla por compás, larga; después las parejas, uno señala y el otro toca.', 'pentagrama'),
   ('5', 'El repaso de la meta', '<i>«¿Qué nota vive en la cuarta línea de la clave de fa? ¿Qué pentagrama lleva las notas graves? ¿Qué tocaba la kithara?»</i>', 'pulgar')],
  cuesta='Leen la clave de fa como si fuera de sol: es el error más común; marquen con color la cuarta línea y cuenten desde ella. Se pierden en el sistema: una regla debajo del pentagrama de abajo. El bordón y la melodía no coinciden: el Seikilos más lento con ♩ PULSE, y la tecla al empezar cada compás.',
  funciono='Al menos <b>3 de cada 4 parejas</b> leen bien las nueve notas del bordón y al menos una pareja lo toca con la melodía; la mayoría dibuja la clave de fa con los puntos en la cuarta línea.',
  final='En el cuaderno, «Escuchar lo de abajo». Reto: el bordón usa Sol, Fa, Mi y Re; ¿qué intervalo hay entre la nota más aguda y la más grave?',
  eval_que='Parejas que leyeron bien el bordón', eval_si_no='empiece la Clase 8 leyendo a coro el bordón del Seikilos (5 min).',
  palabras=[('Clave de fa', 'Marca la cuarta línea como Fa. Es la casa de las notas graves.'), ('Clave de do', 'La línea donde está la clave es Do. La usa la viola.'),
   ('Sistema', 'Dos o más pentagramas que suenan juntos, unidos por una barra.'), ('Bordón', 'Una nota grave y larga que suena siempre igual, como en la gaita o la kithara.'),
   ('Kithara', 'La lira de los griegos; tocaba el bordón del Seikilos.'), ('Aulos', 'La flauta doble de los griegos; tocaba la melodía.'),
   ('Las líneas en fa', 'Sol, Si, Re, Fa, La, de abajo hacia arriba.'), ('Los espacios en fa', 'La, Do, Mi, Sol.')])

_n2('8', 'aula-n2-clase-8-es.html', 'Las tonalidades', 'La llave de la tonalidad', [33, 34, 35, 36],
  gram_desc='«La llave de la tonalidad»: por qué existe la armadura, los dos trucos y «¿De qué tonalidad es?».',
  meta='Cada pareja <b>mira cuatro armaduras y dice la tonalidad mayor de cada una con los dos trucos</b>; la clase confirma con el pulgar. Además: decir la relativa menor de una tonalidad mayor, y tocar en el Keyboard la sensible y la tónica.',
  necesita=f'Un computador con parlante e internet, el {KB}, las obras del Score que la clase ya conoce («Alla Turca», «Ave Maria», la Sinfonía de Bach, la «Oda», Ravel), la pizarra (y un proyector, si hay).',
  antes=['Aprenda de memoria el orden de los sostenidos: Fa, Do, Sol, Re, La, Mi, Si. El de los bemoles, al revés.', 'Pruebe los dos trucos con las armaduras de la ficha.', f'En el {KB}: SYSTEM Tonal, KEY C, MODE M. En la fila del medio, {k("A")} es la tónica, {k("J")} la sensible, {k("K")} el Do de arriba: toque {k("J")} y deje que la mano vaya sola a {k("K")}.'],
  etapas=[('3', 'La meta', '<i>«Esos sostenidos o bemoles del comienzo nos dicen dónde está la casa de la música.»</i> En la pizarra: <b>Puedo leer una armadura y decir su tonalidad.</b>', 'pizarra'),
   ('5', 'Lo que ya saben: la escalera mayor', 'La escalera de Do cantada con los nombres; los dos semitonos diatónicos, Mi–Fa y Si–Do. En la pizarra: T T S T T T S.', 'escalera'),
   ('20', 'Lo nuevo: la armadura, los trucos y la relativa', '<b>La escalera desde Re</b>: ¿dónde se rompe la forma? Fa♯ y Do♯, escritos una sola vez al comienzo: la armadura. <b>El orden</b>, como un trabalenguas. <b>Los dos trucos</b>: el último sostenido es la sensible; el penúltimo bemol es la tonalidad. <b>La relativa y la sensible</b>: la menor empieza en el sexto grado.', 'armadura'),
   ('17', 'Aplicación: ¿de qué tonalidad es?', f'<b>Las obras conocidas</b>: la clase lee la armadura de cada una y dice la tonalidad; ¿mayor o su relativa menor? <b>La ficha</b>: cada armadura con su mayor y su relativa. <b>La sensible en el teclado</b>: uno toca {k("J")} y el otro la resuelve en {k("K")}.', 'piano'),
   ('5', 'El repaso de la meta', 'Cuatro armaduras a coro. <i>«¿Cuál es el truco de los sostenidos? ¿Y el de los bemoles? ¿Qué nota empuja hacia la casa?»</i>', 'pulgar')],
  cuesta='No recuerdan el orden: una frase propia con las iniciales. Con sostenidos dicen la nota del último: el último es la sensible, la casa está un escalón arriba. Con un bemol buscan el penúltimo: un bemol es Fa mayor, de memoria. Confunden la relativa: seis notas desde la tónica, o una tercera hacia abajo.',
  funciono='Al menos <b>3 de cada 4 parejas</b> dicen la tonalidad mayor de las cuatro armaduras; la mayoría escribe bien al menos cuatro de las seis relativas de la ficha, y las parejas del Keyboard resuelven la sensible sin ayuda.',
  final=f'La {a(S + "/suite/armonia-maquina.html?lang=es", "máquina de armonía")}: elegir una tonalidad y escucharla.',
  eval_que='Parejas que dijeron las cuatro tonalidades', eval_si_no='empiece la Clase 9 diciendo el orden de los sostenidos como un trabalenguas (5 min).',
  palabras=[('Armadura', 'Los sostenidos o bemoles del comienzo de cada pentagrama: valen para toda la obra.'), ('Tonalidad', 'La casa de la música: su tónica y su escalera, mayor o menor.'),
   ('Tónica', 'La nota casa: ahí empieza y termina la melodía.'), ('Sensible', 'El séptimo grado, un semitono diatónico debajo de la tónica: empuja hacia casa.'),
   ('Relativa menor', 'La hermana menor de una tonalidad mayor: misma armadura, empieza en el sexto grado. Do mayor → la menor.'), ('El orden de los sostenidos', 'Fa, Do, Sol, Re, La, Mi, Si. Los bemoles, al revés.'),
   ('Truco de los sostenidos', 'El último sostenido es la sensible: la tonalidad está un escalón arriba.'), ('Truco de los bemoles', 'El penúltimo bemol es la tonalidad. Con uno solo, Fa mayor.')])

_n2('9', 'aula-n2-clase-9-es.html', 'Matices y articulaciones', 'Las mismas notas, otra música', [37, 38, 39, 40],
  gram_ref='cap. 9, págs. 37–40, y «Fuerte y suave en todo el mundo», págs. 41–42',
  gram_desc='«Las mismas notas, otra música» y «Las dos ligaduras» (págs. 37 a 40); «Fuerte y suave en todo el mundo» (págs. 41 y 42).',
  meta=f'Cada pareja <b>escribe matices y articulaciones en cuatro compases de la «Oda a la alegría» y los toca en el Keyboard</b>; la clase adivina qué signos usaron. Además: ordenar los matices de pp a ff, distinguir las dos ligaduras, y solfear una melodía conocida siguiendo sus signos.',
  necesita=f'Un computador con parlante e internet, el {KB}, las dos versiones de la «Oda» en el Score ({ODA} y {ODAM}), la pizarra (y un proyector, si hay).',
  antes=['Escuche las dos versiones de la Oda mirando la partitura: las notas son las mismas; cambia cómo se tocan.', f'Toque la Oda con la fila del medio: {k("D D F G G F D S")} · {k("A A S D D S S")}.', 'Tóquela soltando cada tecla enseguida (staccato) y dejándola hasta la siguiente (legato); gire la perilla <b>VOL</b> mientras toca.'],
  etapas=[('3', 'La meta', '<i>«Una partitura también dice si tocar suave o fuerte, corto o largo.»</i> En la pizarra: <b>Puedo leer y tocar matices y articulaciones.</b>', 'pizarra'),
   ('5', 'Lo que ya saben: dos versiones de la misma melodía', 'La Oda cantada con los nombres; después las dos versiones seguidas. <i>«¿Qué cambió, si las notas son las mismas?»</i>', 'cancion'),
   ('20', 'Lo nuevo: los signos', '<b>La escalera de los matices</b>, de pp a ff, y el sfz y el fp con una palmada. <b>Solfeo con matices</b>: «Estrellita» con p y f debajo, primero dicha y después cantada. <b>Los reguladores</b>: crescendo y diminuendo. <b>Las articulaciones</b>: staccato, acento, tenuto y calderón. <b>Las dos ligaduras</b>.', 'matices'),
   ('17', 'Aplicación: la Oda de cada pareja', f'<b>Escribir</b>: en los compases 5 a 8, al menos un matiz, un regulador y dos articulaciones. <b>Tocar</b>: usted primero; un alumno toca y otro gira <b>VOL</b> para los matices. <b>Adivinar</b>: la clase dice qué signos usó cada pareja.', 'piano'),
   ('5', 'El repaso de la meta', 'La Oda con matices: la clase levanta la mano en cada cambio. <i>«¿Qué es más suave, p o mp? ¿Qué hace un punto encima de una nota? ¿Cuál ligadura une dos notas iguales?»</i>', 'pulgar')],
  cuesta='Confunden p y f: «p» de poquito, «f» de fuerte. El crescendo sale de golpe: un peldaño por nota, contando en voz alta. No distinguen las ligaduras: si las dos notas son iguales, es de prolongación. El de VOL se adelanta: que siga la partitura con el dedo.',
  funciono='Al menos <b>3 de cada 4 parejas</b> escriben un matiz, un regulador y dos articulaciones en su lugar, y la clase adivina al menos la mitad de los signos; la mayoría ordena los matices de pp a ff y distingue las dos ligaduras.',
  final='En el cuaderno, «Fuerte y suave en todo el mundo». Reto: el teclado de la computadora no sabe con cuánta fuerza se aprieta; ¿qué instrumento sí?',
  eval_que='Parejas que escribieron y tocaron sus signos', eval_si_no='empiece la Clase 10 con la escalera de los matices dicha a coro (5 min).',
  palabras=[('Matiz', 'Con qué fuerza suena la música: pp, p, mp, mf, f, ff.'), ('Regulador', 'Crescendo: cada vez más fuerte. Diminuendo: cada vez más suave.'),
   ('Sforzando (sf)', 'Un golpe fuerte en una sola nota. El fp ataca fuerte y baja enseguida a piano.'), ('Staccato', 'Un punto encima o debajo: la nota corta.'),
   ('Acento y tenuto', 'El acento (>) empieza fuerte; el tenuto (–), la nota llena.'), ('Calderón', 'La nota se queda hasta que el director decide.'),
   ('Ligadura de prolongación', 'Une dos notas iguales: suenan como una sola, más larga.'), ('Ligadura de expresión', 'Une notas distintas: se tocan juntas, sin cortar (legato).')])
